$ErrorActionPreference = "Continue"
$workspace = "C:\Users\User\Documents\blender_tasks\blender_restage_product"
$scenePath = Join-Path $workspace "product_stage.blend"
$blenderExeCandidates = @(
  "C:\Tools\Blender279b\blender-2.79b-windows64\blender.exe",
  "C:\Program Files\Blender Foundation\Blender 2.79\blender.exe",
  "C:\Program Files\Blender Foundation\Blender\blender.exe",
  "$env:LOCALAPPDATA\Programs\Blender Foundation\Blender\blender.exe"
)
$blenderExe = $blenderExeCandidates | Where-Object { Test-Path $_ } | Select-Object -First 1
if (-not $blenderExe) {
  $cmd = Get-Command blender.exe -ErrorAction SilentlyContinue
  if ($cmd) { $blenderExe = $cmd.Source }
}
if (-not $blenderExe -or -not (Test-Path $blenderExe)) { throw "Blender executable not found" }
function Fail($message) { Write-Output "EVAL_RESULT:FAIL $message"; exit 1 }
function Assert-Close($actual, $expected, $label, $tolerance = 0.08) { if ([math]::Abs([double]$actual - [double]$expected) -gt $tolerance) { Fail "$label expected $expected but got $actual" } }
function Assert-Vec($actual, $expected, $label, $tolerance = 0.08) { for ($i = 0; $i -lt $expected.Count; $i++) { Assert-Close $actual[$i] $expected[$i] "$label[$i]" $tolerance } }
function Has-Prop($obj, $name) { return $obj.PSObject.Properties.Name -contains $name }
$expectedJson = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
$expected = $expectedJson | ConvertFrom-Json
$inspect = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(""))
$inspectPath = Join-Path $env:TEMP "inspect_blender_warehouse_blockout_scene.py"
Set-Content -LiteralPath $inspectPath -Value $inspect -Encoding UTF8
function Inspect-Blend($path) {
  if (-not (Test-Path $path)) { Fail "blend file missing: $path" }
  $jsonPath = Join-Path $env:TEMP (([IO.Path]::GetFileNameWithoutExtension($path)) + "_blender_warehouse_blockout_scene.json")
  $env:HW_SCENE_JSON_PATH = $jsonPath
  if (Test-Path $jsonPath) { Remove-Item -LiteralPath $jsonPath -Force }
  $raw = & $blenderExe --background $path --python $inspectPath 2>&1 | Out-String
  if ($LASTEXITCODE -ne 0) { Fail "Blender inspection failed for $path exit=$LASTEXITCODE output=$raw" }
  if (-not (Test-Path $jsonPath)) { Fail "inspection output missing for $path" }
  return Get-Content -LiteralPath $jsonPath -Raw | ConvertFrom-Json
}
function Normalize-RenderValue($value) {
  if ($null -eq $value) { return $value }
  $text = [string]$value
  if ($text.StartsWith("//")) { return ($text -replace "\\", "/") }
  return $value
}
function Check-Render($scene, $render, $label) {
  foreach ($prop in $render.PSObject.Properties) {
    $actual = Normalize-RenderValue $scene.render.($prop.Name)
    $expectedValue = Normalize-RenderValue $prop.Value
    if ($actual -ne $expectedValue) { Fail "$label render $($prop.Name) expected $($prop.Value) got $($scene.render.($prop.Name))" }
  }
}
function Check-Object($scene, $spec, $label) {
  if (-not (Has-Prop $scene.objects $spec.name)) { Fail "$label missing object $($spec.name)" }
  $obj = $scene.objects.($spec.name)
  if (($spec.PSObject.Properties.Name -contains "type") -and $obj.type -ne $spec.type) { Fail "$label $($spec.name) type expected $($spec.type) got $($obj.type)" }
  if ($spec.PSObject.Properties.Name -contains "location") { Assert-Vec $obj.location $spec.location "$label $($spec.name).location" }
  if ($spec.PSObject.Properties.Name -contains "rotation_degrees") { Assert-Vec $obj.rotation_degrees $spec.rotation_degrees "$label $($spec.name).rotation" 0.8 }
  if ($spec.PSObject.Properties.Name -contains "scale") { Assert-Vec $obj.scale $spec.scale "$label $($spec.name).scale" }
  if ($spec.PSObject.Properties.Name -contains "material_diffuse_color") { Assert-Vec $obj.material_diffuse_color $spec.material_diffuse_color "$label $($spec.name).color" 0.04 }
}
$primary = Inspect-Blend $scenePath
Check-Render $primary $expected.primary_render "primary"
foreach ($spec in $expected.objects) { Check-Object $primary $spec "primary" }
foreach ($extra in $expected.additional) { $scene = Inspect-Blend $extra.path; Check-Render $scene $extra.render $extra.label; foreach ($spec in $extra.objects) { Check-Object $scene $spec $extra.label } }
foreach ($artifact in $expected.text_artifacts) { if (-not (Test-Path $artifact.path)) { Fail "text artifact missing: $($artifact.path)" }; $content = (Get-Content -LiteralPath $artifact.path -Raw) -replace "`r`n","`n"; $want = $artifact.content -replace "`r`n","`n"; if ($content.TrimEnd("`n") -ne $want.TrimEnd("`n")) { Fail "text artifact content mismatch: $($artifact.path)" } }
Write-Output "EVAL_RESULT:PASS blender_warehouse_blockout_scene Linux-aligned Blender deliverables verified"
